// Turn viewers: side-by-side base / ours frames with a turn slider.
// Sequence data (titles, instructions) comes from sequences.js, generated by tools/build_assets.py.

(function () {
  "use strict";

  const SEQ = window.SEQUENCES;
  const METHODS = [
    { key: "base", label: "FLUX.2 Klein" },
    { key: "ours", label: "FLUX.2 Klein + Ours" },
  ];
  const PLAY_MS = 700;

  const ICONS = {
    play: '<svg viewBox="0 0 12 12" aria-hidden="true"><path d="M2 1l9 5-9 5z"/></svg>',
    pause: '<svg viewBox="0 0 12 12" aria-hidden="true"><path d="M2 1h3v10H2zM7 1h3v10H7z"/></svg>',
  };

  const frameSrc = (seq, method, t) =>
    `static/seq/${seq}/${method}/${String(t).padStart(2, "0")}.webp`;

  // Decoded-image cache: url -> Promise that resolves once the frame is decoded.
  // Holding the Image objects keeps their decoded data around for instant swaps.
  const cache = new Map();
  function load(url) {
    if (!cache.has(url)) {
      const im = new Image();
      im.src = url;
      cache.set(url, im.decode().then(() => im, () => im));
    }
    return cache.get(url);
  }
  function preload(seq) {
    for (let t = 0; t <= SEQ[seq].turns; t++) {
      for (const m of METHODS) load(frameSrc(seq, m.key, t));
    }
  }

  function el(tag, cls, html) {
    const e = document.createElement(tag);
    if (cls) e.className = cls;
    if (html !== undefined) e.innerHTML = html;
    return e;
  }

  class TurnViewer {
    constructor(root) {
      this.root = root;
      this.timer = null;
      this.build();
      this.setSequence(root.dataset.seq);
      if (root.dataset.autoplay === "true") this.autoplayWhenVisible();
    }

    build() {
      const r = this.root;
      r.innerHTML = "";

      this.panels = el("div", "tv-panels");
      // Each panel holds two stacked <img> buffers. A new frame is decoded into the
      // hidden one and only then brought to the front, so frames never flash blank.
      this.buffers = {};
      this.front = 0;
      this.swapToken = 0;
      for (const m of METHODS) {
        const p = el("div", `tv-panel tv-${m.key}`);
        const frame = el("div", "tv-frame");
        const bufs = [el("img"), el("img")];
        bufs.forEach((b) => { b.alt = m.label; frame.append(b); });
        bufs[0].classList.add("is-front");
        this.buffers[m.key] = bufs;
        frame.append(el("div", "tv-label", m.label));
        p.append(frame);
        this.panels.append(p);
      }

      this.info = el("div", "tv-info");
      this.turnLabel = el("span", "tv-turn");
      this.kindTag = el("span", "tv-kind");
      this.instr = el("span", "tv-instr");
      this.info.append(this.turnLabel, this.kindTag, this.instr);

      const controls = el("div", "tv-controls");
      this.playBtn = el("button", "tv-play", ICONS.play);
      this.playBtn.type = "button";
      this.playBtn.setAttribute("aria-label", "Play");
      this.playBtn.addEventListener("click", () => this.toggle());

      const track = el("div", "tv-track");
      this.ticks = el("div", "tv-ticks");
      this.slider = el("input", "tv-slider");
      this.slider.type = "range";
      this.slider.min = 0;
      this.slider.step = 1;
      this.slider.setAttribute("aria-label", "Editing turn");
      this.slider.addEventListener("input", () => { this.stop(); this.show(+this.slider.value); });
      track.append(this.ticks, this.slider);
      controls.append(this.playBtn, track);

      this.history = el("div", "tv-history");

      r.append(this.panels, this.info, controls, this.history);

      r.tabIndex = 0;
      r.addEventListener("keydown", (e) => {
        if (e.key === "ArrowRight") { this.stop(); this.show(Math.min(this.t + 1, this.n)); e.preventDefault(); }
        if (e.key === "ArrowLeft") { this.stop(); this.show(Math.max(this.t - 1, 0)); e.preventDefault(); }
        if (e.key === " ") { this.toggle(); e.preventDefault(); }
      });
    }

    setSequence(seq) {
      this.stop();
      this.seq = seq;
      const d = SEQ[seq];
      this.n = d.turns;
      this.slider.max = this.n;
      preload(seq);

      // Ticks: one per turn, colored by instruction kind.
      this.ticks.innerHTML = "";
      for (let t = 0; t <= this.n; t++) {
        const kind = t === 0 ? "orig" : d.instructions[t - 1].kind;
        const tick = el("span", `tv-tick tv-tick-${kind}`);
        tick.title = t === 0 ? "Original" : `Turn ${t}: ${d.instructions[t - 1].text}`;
        tick.addEventListener("click", () => { this.stop(); this.show(t); });
        this.ticks.append(tick);
      }

      // History chips: the real edits only.
      this.history.innerHTML = "";
      this.chips = [];
      d.instructions.forEach((ins, i) => {
        if (ins.kind !== "edit") return;
        const chip = el("button", "tv-chip", `<b>${i + 1}</b> ${ins.text}`);
        chip.type = "button";
        chip.addEventListener("click", () => { this.stop(); this.show(i + 1); });
        chip.dataset.turn = i + 1;
        this.history.append(chip);
        this.chips.push(chip);
      });

      this.show(0);
    }

    // Swap both panels to turn t together, once both frames are decoded.
    // Returns a promise that resolves when the swap happened (or was superseded).
    swapFrames(t) {
      const token = ++this.swapToken;
      const urls = METHODS.map((m) => frameSrc(this.seq, m.key, t));
      return Promise.all(urls.map(load)).then(() => {
        if (token !== this.swapToken) return;
        const back = 1 - this.front;
        const ready = METHODS.map((m, i) => {
          const img = this.buffers[m.key][back];
          if (img.getAttribute("src") !== urls[i]) img.src = urls[i];
          return img.decode().catch(() => {});
        });
        return Promise.all(ready).then(() => {
          if (token !== this.swapToken) return;
          for (const m of METHODS) {
            this.buffers[m.key][back].classList.add("is-front");
            this.buffers[m.key][this.front].classList.remove("is-front");
          }
          this.front = back;
        });
      });
    }

    show(t) {
      this.t = t;
      this.slider.value = t;
      const swapped = this.swapFrames(t);

      const d = SEQ[this.seq];
      this.turnLabel.textContent = t === 0 ? "Original" : `Turn ${t} / ${this.n}`;
      if (t === 0) {
        this.kindTag.className = "tv-kind tv-kind-orig";
        this.kindTag.textContent = "source";
        this.instr.textContent = "Input image";
      } else {
        const ins = d.instructions[t - 1];
        this.kindTag.className = `tv-kind tv-kind-${ins.kind}`;
        this.kindTag.textContent = { edit: "edit", noop: "no-op", filler: "filler" }[ins.kind];
        this.instr.textContent = `“${ins.text}”`;
      }

      this.ticks.querySelectorAll(".tv-tick").forEach((tk, i) => tk.classList.toggle("is-past", i <= t));
      for (const c of this.chips) {
        const ct = +c.dataset.turn;
        c.classList.toggle("is-done", ct <= t);
        c.classList.toggle("is-current", ct <= t && !this.chips.some((o) => +o.dataset.turn > ct && +o.dataset.turn <= t));
      }
      return swapped;
    }

    play() {
      if (this.timer) return;
      if (this.t >= this.n) this.show(0);
      this.playBtn.innerHTML = ICONS.pause;
      this.playBtn.setAttribute("aria-label", "Pause");
      // Advance only after the current frame is on screen, so slow loads never skip frames.
      const step = () => {
        if (this.t >= this.n) { this.stop(); return; }
        this.show(this.t + 1).then(() => {
          if (this.timer) this.timer = setTimeout(step, PLAY_MS);
        });
      };
      this.timer = setTimeout(step, PLAY_MS);
    }

    stop() {
      clearTimeout(this.timer);
      this.timer = null;
      this.playBtn.innerHTML = ICONS.play;
      this.playBtn.setAttribute("aria-label", "Play");
    }

    toggle() { this.timer ? this.stop() : this.play(); }

    autoplayWhenVisible() {
      if (!("IntersectionObserver" in window)) return;
      const io = new IntersectionObserver((entries) => {
        if (entries.some((e) => e.isIntersecting)) {
          setTimeout(() => this.play(), 600);
          io.disconnect();
        }
      }, { threshold: 0.5 });
      io.observe(this.root);
    }
  }

  function buildDriftStrip(root) {
    const { seq, method } = root.dataset;
    const turns = root.dataset.turns.split(",").map(Number);
    for (const t of turns) {
      const f = el("figure", "drift-frame");
      const img = el("img");
      img.src = frameSrc(seq, method, t);
      img.alt = t === 0 ? "Original" : `Turn ${t}`;
      img.loading = "lazy";
      f.append(img, el("figcaption", "", t === 0 ? "Original" : `Turn ${t}`));
      root.append(f);
    }
  }

  // Static result strips laid out like the paper's teaser: an Original column, then the
  // turn that closes each edit's block (the edit plus the no-op/filler turns after it),
  // with that edit's instruction shown above the boundary between the two columns.
  function stripColumns(seq) {
    const d = SEQ[seq];
    const edits = [];
    d.instructions.forEach((ins, i) => { if (ins.kind === "edit") edits.push(i + 1); });
    return edits.map((t, k) => ({
      turn: k + 1 < edits.length ? edits[k + 1] - 1 : d.turns,
      text: d.instructions[t - 1].text,
    }));
  }

  // One slide: a label column plus one "step" per shown turn. On wide screens the steps
  // dissolve into a single grid (paper-teaser layout); on phones each step becomes its own
  // row with the two methods side by side.
  function buildResultStrip(seq) {
    const cols = stripColumns(seq);
    const fig = el("figure", "result");
    const grid = el("div", "result-grid");
    grid.style.setProperty("--cols", cols.length + 1);

    const labels = el("div", "rg-labels");
    labels.append(el("div", "rg-corner"));
    for (const m of METHODS) labels.append(el("div", `rg-label rg-label-${m.key}`, `<span>${m.label}</span>`));
    labels.append(el("div", "rg-corner"));
    grid.append(labels);

    const head = el("div", "rg-mobile-head");
    for (const m of METHODS) head.append(el("span", `rg-label-${m.key}`, m.label));
    grid.append(head);

    const steps = [{ turn: 0, text: null }, ...cols];
    for (const c of steps) {
      const step = el("div", "rg-step");
      const instr = el("div", "rg-instr");
      if (c.text) {
        const inner = el("div", "rg-instr-inner");
        inner.append(el("span", "rg-instr-text", `\u201c${c.text}\u201d`));
        inner.insertAdjacentHTML("beforeend",
          '<div class="rg-arc-wrap" aria-hidden="true">' +
          '<svg class="rg-arc" viewBox="0 0 100 20" preserveAspectRatio="none">' +
          '<path d="M0,20 C18,1 82,1 100,20" vector-effect="non-scaling-stroke"/></svg>' +
          '<span class="rg-arrow"></span></div>');
        instr.append(inner);
      } else {
        instr.classList.add("is-empty");
      }
      step.append(instr);
      for (const m of METHODS) {
        const img = el("img", `rg-img rg-img-${m.key}`);
        img.src = frameSrc(seq, m.key, c.turn);
        img.alt = `${m.label}, ${c.turn === 0 ? "original" : `edit ${c.turn}`}`;
        img.loading = "lazy";
        img.decoding = "async";
        step.append(img);
      }
      step.append(el("div", "rg-cap", c.turn === 0 ? "Original" : `Edit #${c.turn}`));
      grid.append(step);
    }

    fig.append(grid);
    return fig;
  }

  function buildCarousel(root) {
    const track = root.querySelector(".carousel-track");
    const dotsBox = root.querySelector(".carousel-dots");
    const seqs = root.dataset.scenes.split(",");
    const slides = seqs.map((seq, k) => {
      const slide = el("div", "carousel-slide");
      slide.setAttribute("aria-roledescription", "slide");
      slide.setAttribute("aria-label", `Example ${k + 1} of ${seqs.length}`);
      slide.append(buildResultStrip(seq));
      track.append(slide);
      return slide;
    });
    const dots = seqs.map((seq, k) => {
      const d = el("button", "carousel-dot");
      d.type = "button";
      d.setAttribute("aria-label", `Show example ${k + 1}`);
      d.addEventListener("click", () => go(k));
      dotsBox.append(d);
      return d;
    });

    let current = 0;
    const go = (k) => {
      k = (k + slides.length) % slides.length;
      track.scrollTo({ left: slides[k].offsetLeft - track.offsetLeft, behavior: "smooth" });
    };
    // A fixed track height (the tallest slide) keeps the box from resizing between examples;
    // shorter slides are centered in it (see .carousel-track in the CSS).
    const fit = () => { track.style.height = `${Math.max(...slides.map((sl) => sl.offsetHeight))}px`; };
    const mark = (k) => {
      current = Math.max(0, Math.min(slides.length - 1, k));
      dots.forEach((d, i) => d.classList.toggle("is-active", i === current));
      fit();
    };
    // On resize, keep the same slide in view (slide widths change with the window).
    window.addEventListener("resize", () => {
      track.scrollTo({ left: slides[current].offsetLeft - track.offsetLeft, behavior: "instant" });
      fit();
    });
    root.querySelectorAll(".carousel-btn").forEach((b) =>
      b.addEventListener("click", () => go(current + +b.dataset.dir)));
    root.tabIndex = 0;
    root.addEventListener("keydown", (e) => {
      if (e.key === "ArrowRight") { go(current + 1); e.preventDefault(); }
      if (e.key === "ArrowLeft") { go(current - 1); e.preventDefault(); }
    });
    // Track which slide is showing (also after swiping on touch screens).
    let raf = 0;
    track.addEventListener("scroll", () => {
      cancelAnimationFrame(raf);
      raf = requestAnimationFrame(() => mark(Math.round(track.scrollLeft / track.clientWidth)));
    });
    mark(0);
  }

  document.addEventListener("DOMContentLoaded", () => {
    const viewers = new Map();
    document.querySelectorAll(".turn-viewer").forEach((v) => viewers.set(v, new TurnViewer(v)));
    document.querySelectorAll(".drift-strip").forEach(buildDriftStrip);

    document.querySelectorAll(".carousel").forEach(buildCarousel);
  });
})();
